import{_ as o,C as d,o as i,c as r,aj as e,E as n}from"./framework.js";const u=JSON.parse('{"title":"在线编辑 | Cms / Site | Documentation","description":"在线编辑 in Kooboo: 在前台真实渲染结果上直接点选元素修改，适合改文案、图片、链接与局部样式，无需手写 HTML。保存后写回对应 Page（或设计页）资源。","frontmatter":{"title":"在线编辑 | Cms / Site | Documentation","description":"在线编辑 in Kooboo: 在前台真实渲染结果上直接点选元素修改，适合改文案、图片、链接与局部样式，无需手写 HTML。保存后写回对应 Page（或设计页）资源。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/site/pages-inline-edit.html"}]]},"headers":[],"relativePath":"zh/cms/site/pages-inline-edit.md","filePath":"cms/site/pages-inline-edit.md","lastUpdated":1780283318000}'),l={name:"zh/cms/site/pages-inline-edit.md"};function s(h,t,c,g,b,p){const a=d("DocImage");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="在线编辑" tabindex="-1">在线编辑 <a class="header-anchor" href="#在线编辑" aria-label="Permalink to &quot;在线编辑&quot;">​</a></h1><blockquote><p>从 <a href="./pages.html">页面列表</a> 行内 <strong>在线编辑</strong> 进入<br> 深链：<code>/_Admin/inline-design?SiteId={站点GUID}&amp;path={页面路径}&amp;id={页面Id}&amp;type={页面类型}</code></p></blockquote><p>在<strong>前台真实渲染结果</strong>上直接点选元素修改，适合改文案、图片、链接与局部样式，无需手写 HTML。保存后写回对应 Page（或设计页）资源。</p><div class="tip custom-block"><p class="custom-block-title">与编辑代码</p><table tabindex="0"><thead><tr><th></th><th>在线编辑</th><th><a href="./pages-edit-code.html">编辑代码</a></th></tr></thead><tbody><tr><td>场景</td><td>运营改字、换图、调样式</td><td>改结构、Layout 占位、View</td></tr><tr><td>界面</td><td>浏览器内嵌页面 + 浮动工具</td><td>Monaco 全屏</td></tr></tbody></table></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li><strong>页面</strong> 列表 → 目标行 → <strong>在线编辑</strong>（笔形图标）。</li><li>通常在新窗口或全屏层打开 <code>/_Admin/inline-design</code>，并带上当前页的 <code>path</code>、<code>id</code>、<code>type</code> 及 <code>SiteId</code>。</li><li>请求预览 URL 时会附加 <code>koobooInline=design</code> 等参数，在页面上叠加编辑层。</li></ol>',6)),n(a,{src:"/cms/site/pages-inline-edit.png",alt:"在线编辑：预览页与浮动工具条",width:"1120"}),t[1]||(t[1]=e('<h2 id="界面概览" tabindex="-1">界面概览 <a class="header-anchor" href="#界面概览" aria-label="Permalink to &quot;界面概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元素</th><th>说明</th></tr></thead><tbody><tr><td>主画面</td><td>站点页面预览（与访客所见一致，含已发布内容）</td></tr><tr><td>元素高亮</td><td>鼠标移入/选中时出现边框（DomBorder）</td></tr><tr><td>右侧浮动工具条</td><td>可拖动：撤销/重做、保存、视口宽度、全局样式/颜色/图片/链接/文本等</td></tr><tr><td>右键菜单</td><td>依选中节点类型显示（编辑文本、图片、链接、组件、内容、重复器等）</td></tr><tr><td>文本浮动条</td><td>选中文字时出现：加粗、颜色、链接、图片等快捷操作</td></tr></tbody></table><p>站点 <strong>在线编辑设置</strong>（<code>inlineDesignSettings</code>）可关闭部分全局按钮（颜色、图片、链接等），以你环境为准。</p><h2 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h2><h3 id="改文字" tabindex="-1">改文字 <a class="header-anchor" href="#改文字" aria-label="Permalink to &quot;改文字&quot;">​</a></h3><ol><li>双击或选中文字区域。</li><li>使用浮动 <strong>文本工具条</strong> 或右键 <strong>编辑文本</strong>。</li><li>修改后确认；变更进入撤销栈。</li></ol><h3 id="改图片-链接" tabindex="-1">改图片 / 链接 <a class="header-anchor" href="#改图片-链接" aria-label="Permalink to &quot;改图片 / 链接&quot;">​</a></h3><ul><li>右键对应元素，或从浮动条选择图片/链接。</li><li>图片可从 <a href="./media.html">媒体库</a> 选择（内嵌媒体对话框）。</li><li>链接可填站内路径或外链。</li></ul><h3 id="改样式" tabindex="-1">改样式 <a class="header-anchor" href="#改样式" aria-label="Permalink to &quot;改样式&quot;">​</a></h3><ul><li>右键 <strong>编辑样式</strong>，或选中元素后在对话框中改 CSS。</li><li>设计页类型可能提供 <strong>全局样式</strong> 入口（浮动条上的页面图标）。</li></ul><h3 id="撤销-保存" tabindex="-1">撤销 / 保存 <a class="header-anchor" href="#撤销-保存" aria-label="Permalink to &quot;撤销 / 保存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td>撤销 / 重做</td><td>浮动条上带角标；有未保存操作时部分菜单会提示先保存</td></tr><tr><td>保存</td><td>有变更时可点；保存后约 0.5s <strong>刷新当前预览页</strong> 以应用结果</td></tr></tbody></table><p>保存后将 DOM 变更写回服务端 Page body。</p><h3 id="视口宽度" tabindex="-1">视口宽度 <a class="header-anchor" href="#视口宽度" aria-label="Permalink to &quot;视口宽度&quot;">​</a></h3><p>浮动条上的 <strong>屏幕尺寸</strong> 可切换常见宽度（桌面/平板/手机），便于检查响应式，不改变真实 URL。</p><h2 id="设计页面-designer" tabindex="-1">设计页面（Designer） <a class="header-anchor" href="#设计页面-designer" aria-label="Permalink to &quot;设计页面（Designer）&quot;">​</a></h2><p>若页面 <code>type</code> 为 <strong>Designer</strong>，在线编辑会加载可视化页面设计器数据，浮动条可能多出 <strong>全局样式</strong> 等项。此类页面列表主入口多为 <strong>设计</strong>，在线编辑作为预览态下的补充。</p><h2 id="权限与限制" tabindex="-1">权限与限制 <a class="header-anchor" href="#权限与限制" aria-label="Permalink to &quot;权限与限制&quot;">​</a></h2><ul><li>需要 <code>pages</code> 的 <strong>edit</strong> 权限。</li><li>复杂结构（大量脚本逻辑、动态列表）可能只适合在 <a href="./pages-edit-code.html">编辑代码</a> 中改。</li><li>存在未保存的撤销记录时，部分「立即生效」类 CMS 编辑（如 Label）可能被拦截并提示先保存。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./pages-setting.html">页面设置</a></td><td>URL、发布、Meta</td></tr><tr><td><a href="./pages-edit-code.html">编辑代码</a></td><td>body 源码</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/binding/">模板引擎 · 绑定</a></td><td><code>k-content</code> 等与在线编辑的关系</td></tr></tbody></table>',21))])}const _=o(l,[["render",s]]);export{u as __pageData,_ as default};
